      this._order.noTaxes = !Tax.isActive();
      this._order.paymentMethod = "card";
      this._order.quantity = Quantity.get();
      this._order.pioupiouTaxInc = 324;
      this._order.pioupiouTaxExc = parseFloat(accounting.toFixed(this._order.pioupiouTaxInc / 120 * 100, 2));
      this._order.pioupiouTotal = parseFloat(accounting.toFixed(this._order.quantity * this._order.pioupiouTaxExc, 2));
