      this._order.discountTaxExc = parseFloat(accounting.toFixed(-this._order.pioupiouTaxExc * 0.15, 2));
      this._order.discountTaxInc = parseFloat(accounting.toFixed(this._order.discountTaxExc * 1.2, 2));
      this._order.discountTotal = parseFloat(accounting.toFixed(this._order.quantity * this._order.discountTaxExc, 2));
