      this._order.warrantyTaxInc = Warranty.getPriceTaxInc();
      this._order.warrantyTaxExc = Warranty.getPriceTaxExc();
      this._order.warrantyTotal = parseFloat(accounting.toFixed(this._order.quantity * this._order.warrantyTaxExc, 2));
      this._order.warrantyDesc = Warranty.getDesc();
      this._order.warrantyId = Warranty.getId();
